        };

        public const int MaskWidth = 416, MaskHeight = 512;
        static bool[] drawn;
        /// <summary>The drawn-water cells, or null when the map's size is not the one the mask was made for.</summary>
        public static bool[] DrawnWater(int width, int height)
        {
            if (width != MaskWidth || height != MaskHeight) return null;
            if (drawn != null) return drawn;
            var bytes = Convert.FromBase64String(string.Concat(MaskB64));
            var d = new bool[width * height];
            for (int i = 0; i < d.Length; i++) d[i] = (bytes[i >> 3] & (1 << (i & 7))) != 0;
            return drawn = d;
        }

